sys_script_include.script:
var ReservaAjaxUtils = Class.create();
ReservaAjaxUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    verificarDisponibilidadeEspaco: function() {
        var espacoId = this.getParameter('sysparm_espaco');
        var dataInicioStr = this.getParameter('sysparm_data_inicio');
        var dataFimStr = this.getParameter('sysparm_data_fim');
        var currentId = this.getParameter('sysparm_sys_id');

        if (!espacoId || !dataInicioStr || !dataFimStr) {
            return 'false';
        }

        var grReserva = new GlideRecord('x_1915295_nexosp_0_x_nexospaces_reserva');
        grReserva.addQuery('espaco', espacoId); 

        // Conversão vital: Recebe o horário da tela (Local) e converte para o formato do banco (UTC)
        var dtInicio = new GlideDateTime();
        dtInicio.setDisplayValue(dataInicioStr);

        var dtFim = new GlideDateTime();
        dtFim.setDisplayValue(dataFimStr);

        // .getValue() aplica a data convertida matematicamente na pesquisa
        grReserva.addQuery('data_inicio', '<', dtFim.getValue());
        grReserva.addQuery('data_fim', '>', dtInicio.getValue());

        // Proteção para ignorar o próprio registo em caso de edição
        if (currentId && currentId != 'undefined' && currentId != '') {
            grReserva.addQuery('sys_id', '!=', currentId);
        }

        grReserva.query();

        if (grReserva.hasNext()) {
            return 'true'; // Achou conflito!
        }

        return 'false'; // Tá livre!
    },

    type: 'ReservaAjaxUtils'
});
